    required this.market,
    required this.timestampNs,
    required this.price,
    required this.quantity,
    required this.takerSide,
    this.id,
  });

  @override
  int get hashCode =>
      market.hashCode ^
      timestampNs.hashCode ^
      price.hashCode ^
      quantity.hashCode ^
      takerSide.hashCode ^
      id.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is WireTrade &&
          runtimeType == other.runtimeType &&
          market == other.market &&
          timestampNs == other.timestampNs &&
          price == other.price &&
          quantity == other.quantity &&
          takerSide == other.takerSide &&
          id == other.id;
}

enum WireTransferErrorKind {
  assetMismatch,
  networkMismatch,
  ambiguousNetwork,
  networkUnavailable,
  memoRequired,
  destinationUnavailable,
  addressNotAllowed,
  travelRuleRequired,
  amountOutOfRange,
  planExpired,
}

class WireUpbitMarketEvent {
  final WireMarket market;
  final bool warning;
  final List<String> cautions;

  const WireUpbitMarketEvent({
    required this.market,
    required this.warning,
    required this.cautions,
  });

  @override
  int get hashCode => market.hashCode ^ warning.hashCode ^ cautions.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is WireUpbitMarketEvent &&
          runtimeType == other.runtimeType &&
          market == other.market &&
          warning == other.warning &&
          cautions == other.cautions;
}
